//! Every cmux command name wmux recognizes, with its usage and a one-line
//! summary (ADR-4.8, Appendix C). Usage strings are cmux interface facts
//! (CLI contract help probes); summaries are wmux wording. `--help` falls
//! back to this table for commands whose family has not registered a
//! `CommandSpec` yet. The topic listings in help/<topic>.txt mirror it
//! (checked by a unit test in help.zig).

const Group = @import("../command.zig").Group;

pub const Entry = struct {
    name: []const u8,
    group: Group,
    usage: []const u8,
    summary: []const u8,
    hidden: bool = false,
};

